def total(nums):
    s = 0                  # 1 step
    for x in nums:         # the body runs n times
        s += x             # 1 step each time: n steps
    return s               # 1 step -> n + 2 steps -> O(n)

def count_pairs(nums):
    pairs = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            pairs += 1     # runs n(n - 1)/2 times -> O(n^2)
    return pairs

print(total([3, 1, 4]), count_pairs([3, 1, 4, 1, 5]))   # 8 10

def find(names, target):
    for i, name in enumerate(names):
        if name == target:
            return i
    return -1

names = ["ana", "ben", "cy", "dee"]
find(names, "ana")   # best case: 1 comparison
find(names, "dee")   # 4 comparisons
find(names, "zed")   # worst case: all 4 comparisons, then -1
# A target equally likely to be anywhere averages about n/2 comparisons: O(n)

# Brute force: check every pair -> O(n^2) time, O(1) extra space
def has_pair_sum(nums, target):
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == target:
                return True
    return False

# Better: remember what you have seen -> O(n) time, O(n) extra space
def has_pair_sum_fast(nums, target):
    seen = set()
    for x in nums:
        if target - x in seen:   # O(1) average lookup
            return True
        seen.add(x)
    return False

print(has_pair_sum([8, 3, 5, 1], 6), has_pair_sum_fast([8, 3, 5, 1], 6))   # True True

